SIGNS = {}
FOLDER = {}
for folder, slug, name, pointers in ROSTER:
    assert slug not in SIGNS, f"duplicate slug {slug}"
    label, sources = TRADITIONS[folder]
    SIGNS[slug] = (name, f"{label} pantheon", pointers, folder, sources)
    FOLDER[slug] = folder

ORDER = [slug for folder in TRADITIONS for (f, slug, _, _) in ROSTER if f == folder]


def out_path(slug):
    return f"{FOLDER[slug]}/{slug}.md"


if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    for slug, (name, status, pointers, folder, sources) in SIGNS.items():
        text = f"""# {name}: research brief

Whole-pantheon build-out, Anthony 2026-09-16, symbols/pantheon/{folder}/. Appended to
PROMPT_TEMPLATE_PANTHEON.md by tools/codex_dossier_set.py.

---

BEING. {name} ({status}). State at the top the being's class (god, goddess, spirit, demon,
monster, collective) as the tradition classifies it, and its earliest secure attestation.

THREADS TO PULL, each to be verified against the sources and dated: {pointers}.

WHERE THE SOURCES ARE for this tradition: {sources}.

STANCE. Legend as fully as fact; nothing discarded for being unprovable, everything labeled.
Where a thread above names a dispute, present both sides with their evidence. Every documented
interaction with another named divine being gets its own line (the other being, the nature of the
interaction, the source and date), since sibling dossiers exist for most of this pantheon and the
files cross-reference by name. Absence of evidence is a finding.
"""
        open(os.path.join(OUT, f"{slug}.brief.md"), "w").write(text)
    from collections import Counter
    print("wrote", len(SIGNS), "briefs:", dict(Counter(FOLDER.values())))
